  'st.session_group': 'Grupo de sesión compartida',
  'st.session_group_ph': 'vacío: no compartida',
  'st.session_group_help': 'Las aplicaciones del mismo grupo (y con el directorio de usuarios como autenticación) comparten el inicio de sesión: tras entrar en una, las demás se abren sin volver a iniciar sesión, cada una con su propia comprobación de acceso y sus roles; cerrar sesión en una la cierra en todas (APEX: session sharing). Minúsculas, dígitos y _.',
