  'rs.users_switch_between_the_ticked': 'Los usuarios cambian entre las vistas marcadas. Las horas fuera del rango se añaden cuando un evento las necesita.',
  'rs.runs_as_the_application_s': 'Se ejecuta con el rol de base de datos de la aplicación (se aplica la seguridad a nivel de fila) con `:EVENT_ID` (el valor de la columna clave), `:NEW_START` y `:NEW_END` (la misma duración que antes). Vacío: los eventos no se pueden arrastrar.',
  'rs.only_events_the_user_sees': 'Solo se pueden mover los eventos que el usuario ve en este calendario; sin ratón, el enlace de edición cambia las fechas.',
  'rs.not_while_the_pointer_or': 'No mientras el puntero o el foco estén en el carrusel, ni para usuarios que prefieren movimiento reducido. Un carrusel no tiene "Mostrar todo".',
  'rs.a_chosen_region_gets_display': 'Una región elegida recibe `"display_selector": true` en su configuración (una pestaña con su nombre) o el nombre de la pestaña: las regiones con el mismo nombre de pestaña comparten una pestaña (p. ej. filtros inteligentes y su informe). Sin JavaScript se muestran todas las regiones, con enlaces a cada una.',
  'rs.gauge_charts_only_a_warning': 'Solo gráficos de indicador. Un umbral de advertencia por encima del crítico significa que los valores bajos son malos (p. ej. advertencia 50, crítico 20).',
  'rs.drill_down_column_takes_the': 'Desglose: `#column#` toma el valor de la fila del punto y `#series#` el nombre de su serie. Las columnas a las que solo se refiere el enlace no se dibujan.',
  'rs.gantt_charts_with_a_task': 'Gráficos de Gantt con una columna `task_id`. Se ejecuta con el rol de base de datos de la aplicación (se aplica la seguridad a nivel de fila) con `:TASK_ID`, `:NEW_START` y `:NEW_END` (`YYYY-MM-DD`, o `YYYY-MM-DDTHH:MM` por horas; un hito recibe el mismo inicio y fin). Vacío: las tareas no se pueden arrastrar.',
  'rs.only_tasks_the_user_sees': 'Solo se pueden mover las tareas que el usuario ve en este gráfico; después el gráfico se vuelve a dibujar a partir de su consulta.',
