  'rs.not_in_query': 'no está en la consulta',
  'rpt.report_settings': 'Configuración del informe',
  'rpt.save_report_settings': 'Guardar configuración del informe',
  'rs.no_position_alert': 'El informe no tiene columnas `lat`/`lng` ni `location`, así que el área del mapa no puede filtrarlo.',
  'rs.facets_help': 'Las casillas muestran los valores más frecuentes (Excluir permite a los usuarios filtrarlos fuera). Rangos y Desde/hasta necesitan una columna numérica o de fecha: los rangos son `from..to = label` separados por `;`, con un extremo abierto vacío (`..1000`, `2020-01-01..`); un rango incluye su inicio, no su fin. Una valoración con estrellas ofrece «4 estrellas o más», etc. (hasta 5; `"max"` en el JSON lo cambia).',
  'rs.facets_help_chart': 'Gráfico: un gráfico de barras o circular de los recuentos bajo la faceta (contraído); una barra o porción filtra por su valor.',
  'rs.calendar_help': 'La consulta devuelve `start_date`, `title` y opcionalmente `end_date` (fechas para eventos de todo el día, marcas de tiempo para eventos con hora).',
  'rs.chart_help': 'La primera columna es la etiqueta; cada columna numérica siguiente es una serie (hasta 8). Un diagrama de Gantt lee `label, start, end` (fechas o marcas de tiempo; un fin vacío es un hito) y columnas opcionales llamadas `progress` (0 a 100), `task_id` y `depends_on` (los ids que espera una tarea, p. ej. `3,4`).',
  'rs.map_help': 'Cada fila es un marcador en `lat`, `lng` (o `location` como "lat,lng"), con `title` y `body` en su ventana emergente; una columna `geojson` dibuja líneas y áreas (con PostGIS instalado también sirve una columna `geometry` o `geography` en WGS 84). Un mapa de calor pondera cada lugar por una columna `weight`.',
  'rs.tree_help': 'La consulta devuelve `id`, `parent_id` y `label` (y opcionalmente `icon`); las filas cuyo padre no está en el resultado son las raíces.',
  'rs.workflow_help': 'Los flujos de trabajo vienen de definiciones de flujo (Componentes compartidos); el SQL de la aplicación los inicia con `meta.start_workflow(…)`.',
  'rs.task_help': 'Las tareas vienen de definiciones de tarea (Componentes compartidos); el SQL de la aplicación las crea con `meta.create_task(…)`.',
