  'rm.openapi_help': 'Impórtelo en Swagger UI, Postman o un generador de clientes. Los parámetros documentados de los manejadores se convierten en sus parámetros de consulta y cuerpos de solicitud.',
  'rm.delete_module_confirm': '¿Eliminar el módulo {name} con todas sus plantillas y manejadores?',
