  'rm.chk.role_problem': 'El rol de base de datos de la aplicación: {problem} Sus manejadores responden 403.',
  'rm.chk.no_role': 'La aplicación no tiene rol de base de datos: los manejadores se ejecutan con el rol de ejecución de pgkiln. Dele su propio rol (Aplicación › Configuración) para que los permisos y la seguridad a nivel de fila sean suyos.',
  'rm.chk.disabled': 'Desactivado: cada manejador responde 404',
  'rm.chk.privilege': 'Privilegio: los llamadores necesitan el rol {roles}',
  'rm.chk.no_privilege': 'Sin roles de privilegio: cualquier token válido de la aplicación (los manejadores pueden añadir roles)',
  'rm.response_as': '{request} como {as}',
  'rm.try_intro': 'Envía la solicitud al endpoint real: un PUT, POST o DELETE cambia datos. {as} una cuenta emite un token de corta duración para ella, como hace App › REST API; sin ella ve lo que obtiene un llamador sin token.',
  'rm.intro': 'Módulos de servicios RESTful: un módulo es una ruta base de una aplicación, sus plantillas son URI con `:parameters` y cada plantilla tiene manejadores por método con su origen: una consulta de colección, una fila única, SQL, un bloque PL/pgSQL o un recurso multimedia. Los manejadores se ejecutan con el rol de base de datos de la aplicación y el llamador como `meta.app_user()`, así que se aplican sus permisos y su seguridad a nivel de fila; los parámetros se enlazan, nunca se pegan en el SQL. Cada módulo tiene un documento OpenAPI. Los módulos pertenecen a su aplicación: viajan con su exportación (también en Componentes compartidos › Servicios RESTful).',
  'rm.source_help': 'Variables de enlace, en mayúsculas: parámetros de ruta ({params}), parámetros de consulta y campos del cuerpo JSON; `:BODY` es el cuerpo entero; `:APP_USER` es el llamador. Los valores se enlazan, nunca se pegan en el SQL. PL/pgSQL: un bloque (`declare … begin … end`, o sentencias) que responde con `perform meta.rest_reply(jsonb_build_object(…), 201)`. Multimedia: una consulta que devuelve `content_type`, `content` y opcionalmente `filename`.',
  'rm.params_help': 'Uno por línea: `name query|body|header [{types}] [required] [description]`. Van al documento OpenAPI y al formulario Probar; si falta uno obligatorio, la respuesta es 400. Un parámetro de cabecera lee la cabecera de la petición con su nombre, con - en lugar de _ (`x_request_id` lee `X-Request-Id`).',
  'rm.e.params_line': 'Parámetros, línea {n}: escriba "name query", "name body" o "name header" y, opcionalmente, un tipo ({types}), "required" y una descripción.',
  'rm.e.choose_app': 'Elija una aplicación de este espacio de trabajo.',
  'rm.e.base_path': 'La ruta base empieza por una letra minúscula: letras, dígitos, _ y - (como máximo 40).',
