  'wres.credentials_intro': 'Credenciales web de {workspace} que sus aplicaciones usan por nombre en orígenes de datos REST, el proceso Invocar API, servidores remotos y almacenamiento de objetos, así que una clave se introduce una vez para el espacio de trabajo. Gana la credencial propia de una aplicación (Componentes compartidos → Credenciales web) con el mismo nombre. Los secretos se cifran con la clave del servidor, nunca se vuelven a mostrar y nunca se exportan.',
  'wres.edit_named': 'Editar {name}',
