  'asst.the_model_calls_them_when': 'El modelo las llama cuando las necesita. SQL: `{"name": "my_leave", "description": "…", "sql": "select … where status = :STATUS", "parameters": {"STATUS": {"type": "string", "enum": ["PENDING", "APPROVED"]}}}`; añada `"writes": true` para una herramienta que cambia datos y `"authz": "SCHEME"` para ofrecerla solo a algunos usuarios. REST: `{"name": "department", "type": "rest", "source": "DEPARTMENT", "description": "…", "parameters": {"dname": {"type": "string"}}}`. Tipos de parámetro: string, integer, number, boolean, date; `"optional": true` permite ninguno.',
  'asst.agent_help': 'Un agente de {link} define el servicio, el prompt del sistema, el esfuerzo de razonamiento, las herramientas y los pasos; guardar con un agente quita el servicio, prompt del sistema, herramientas y rondas propios de la región.',
