  'dts.intro': 'Los datasets son vistas de confianza de los datos de {workspace} para usuarios de negocio: tablas y vistas de un esquema, combinadas, con las columnas que pueden ver, etiquetas, máscaras de formato y descripciones, y un filtro de filas. Una aplicación de informes sobre uno o más datasets permite a sus usuarios crear, guardar, publicar y compartir informes; cada informe se ejecuta con el rol de base de datos de la aplicación, así que se aplican los permisos y la seguridad a nivel de fila.',
